"""Bounded AI evidence assessment of historical text, never a legal certification or training launch."""
from pathlib import Path
from html.parser import HTMLParser
import hashlib,json,re,sys
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT))
from foundation.validation import validate_schema,load_ledger,clear_source
RAW=ROOT/'rights/raw/author-revision-candidate-2026-10-25';EV=ROOT/'rights/evidence/author-revision-followup-2026-10-25';OUT=ROOT/'artifacts/author-revision-followup-2026-10-26';LEDGER=ROOT/'rights/author-revision-followup-v1.scoped.jsonl'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
class Text(HTMLParser):
 def __init__(self):super().__init__();self.parts=[]
 def handle_data(self,text):self.parts.append(text)
def words(s):return ' '.join(re.findall(r'\w+',s.casefold()))
def main():
 for item in json.loads(Path(__file__).with_name('evidence-lock.json').read_text()):assert sha(ROOT/item['path'])==item['sha256'],item['path']
 OUT.mkdir(exist_ok=False)
 candidate=json.loads((ROOT/'artifacts/author-revision-candidate-2026-10-25/candidate.json').read_text())
 original_lock=json.loads((ROOT/'curation/author-revision-candidate-v1/source-lock.json').read_text())
 for item in original_lock['sources']:assert sha(ROOT/item['raw_path'])==item['raw_sha256']
 parser=Text();parser.feed((EV/'dickens-1890-chapter.html').read_text());comparison=' '.join(parser.parts)
 assert words(candidate['target']['text']) in words(comparison)
 metadata=json.loads((EV/'forster-scan-metadata.json').read_text())['metadata']
 assert metadata['date']=='1874' and 'Chapman' in metadata['publisher'] and 'NOT_IN_COPYRIGHT'==metadata['possible-copyright-status']
 images=json.loads((EV/'scan-images.manifest.json').read_text())
 for item in images:assert sha(ROOT.parent.parent/item['path'])==item['sha256']
 scope=[]
 for label,number,sid in [('input',25851,'dickens-discarded-ending-pg25851-scoped'),('target',1400,'dickens-published-ending-pg1400-scoped')]:
  source=(RAW/f'pg{number}.txt').read_text(encoding='utf-8');text=candidate[label]['text'].replace('\r\n','\n');assert source.count(text)==1;start=source.index(text)
  scope.append(dict(id=sid,number=number,start=start,end=start+len(text),text=text,sha256=hashlib.sha256(text.encode()).hexdigest(),coordinate_system='Python UTF-8 text read with universal newline conversion, matching foundation.clear_source; original CRLF offsets retained in prior source-lock.json'))
 (OUT/'selected-spans.json').write_text(json.dumps(scope,ensure_ascii=False,indent=2)+'\n');scope_hash=sha(OUT/'selected-spans.json')
 records=[]
 for span in scope:
  number=span['number'];bio=number==25851;url=f'https://www.gutenberg.org/ebooks/{number}';source=RAW/f'pg{number}.txt'
  record=dict(schema_version='1.0',id=span['id'],work_id='great-expectations-discarded-ending' if bio else 'great-expectations',title='Dickens discarded ending, as printed by Forster' if bio else 'Great Expectations: selected final encounter',source_kind='public_domain_candidate',author_ids=['charles-dickens','john-forster'] if bio else ['charles-dickens'],contributors=[dict(name='Charles Dickens',role='author of included fiction prose',life_dates='1812–1870')]+([dict(name='John Forster',role='historical editor transmitting the discarded ending; surrounding biography and framing excluded',life_dates='1812–1876')] if bio else []),publication=dict(original_year=1874 if bio else 1861,edition='Pinned PG25851 digital artifact. Included discarded ending corroborated against Chapman and Hall, London, 1874, Vol III p336, scan leaf362. This is a comparison edition, not proof of the physical copy used for PG.' if bio else 'Pinned PG1400 digital artifact. Included final encounter has the same normalized word sequence as scan-backed validated 1890 P. F. Collier Wikisource Chapter LIX. Exact physical copy used by PG is unidentified; punctuation/layout facsimile equivalence is not claimed.',publisher='Project Gutenberg digital transcription; historical comparison Chapman and Hall' if bio else 'Project Gutenberg digital transcription; historical comparison P. F. Collier and Son, New York',evidence=[url,'https://archive.org/details/lifecharlesdick01unkngoog' if bio else 'https://en.wikisource.org/wiki/Great_Expectations_(1890)/Chapter_LIX']),source=dict(url=next(x['url'] for x in original_lock['sources'] if x['url'].endswith(f'pg{number}.txt')),retrieved_on='2026-10-25',revision='sha256:'+sha(source),raw_path=str(source.relative_to(ROOT/'rights')),sha256=sha(source),included_material=f'Only exact source span {span["start"]}:{span["end"]} in artifacts/author-revision-followup-2026-10-26/selected-spans.json, file SHA256 {scope_hash}. Coordinates follow foundation universal-newline decoding; not whole ebook.',excluded_material='All provider headers, footer, notices, branding, catalogue summaries, biographical commentary, footnote wrappers, illustrations, modern introductions and annotations; all nonselected prose. Layout/image files are evidence only, never teaching targets.',terms_evidence=[url,'https://www.gutenberg.org/policy/permission.html','https://www.gutenberg.org/policy/license.html','https://www.gutenberg.org/policy/terms_of_use.html'],terms_decision='AI evidence assessment supports private GB/US training and evaluation only for selected unbranded expired original prose. Full notices and acquired bytes retained. No branded redistribution, publication, upload or claim of provider endorsement authorised. No special copyright-holder-permission header applies to these catalogue-public-domain items.',notices='Original acquired ebook bytes/notices retained under rights/raw. Rights review concerns original historical prose, not provider apparatus or separately protected additions. PG states that transcriptions may modernize formatting; no claim of an exact physical-copy facsimile.'),clearances=[dict(jurisdiction='GB',basis='Selected material was published by 1874 (discarded ending) or 1890 (comparison novel ending), before 1989. Dickens died 1870 and Forster 1876: ordinary life-plus-70 literary terms have elapsed, even considering the later death. No previously unpublished modern release, modern contributions or published-page layout is included.',uses=['training','evaluation'],evidence=['https://www.gov.uk/copyright/how-long-copyright-lasts',url,'https://archive.org/details/lifecharlesdick01unkngoog']),dict(jurisdiction='US',basis='Both exact PG items identify public domain in USA; underlying selected prose is historically published in the nineteenth century, beyond applicable historical maximum terms. Modern independent additions excluded. US Copyright Office Circular15A records the historical 95-year maximum.',uses=['training','evaluation'],evidence=[url,'https://www.copyright.gov/circs/circ15a.pdf'])],unresolved_issues=[],review=dict(status='approved',reviewer='Codex AI: bounded historical original-prose evidence assessment',reviewed_on='2026-10-26',notes='AI assessment only: not human approval, author consent or legal certification. Exact digital bytes/spans and a limited original-prose use are approved within the standing permission-free source scope. Physical-source and punctuation-equivalence limitations are disclosed and not treated as rights to modern additions. This assessment does not put the pair in training.'))
  validate_schema(record,'rights-record');records.append(record)
 with LEDGER.open('x') as f:
  for record in records:f.write(json.dumps(record,ensure_ascii=False)+'\n')
 index=load_ledger(LEDGER)
 for span in scope:
  for use in ['training','evaluation']:assert clear_source(index[span['id']],LEDGER,['GB','US'],use)[span['start']:span['end']]==span['text']
 report=dict(passed=True,assessment='AI scoped evidence review, not human approval or legal certification',source_records=2,selected_spans_sha256=scope_hash,original_ending_printed_evidence='Forster 1874 volumeIII p336 visually inspected, title and revision account p335 also inspected',target_collation='Entire selected normalized word sequence matches validated 1890 scan-backed Chapter LIX; punctuation and layout equivalence not claimed; direct image fetch attempts were blocked HTTP403',human_approval_recorded=False,training_membership=False,training_gate='Structural alternative ending, not minimal copyedit. Kept outside short-context v3 experiment; exact token budget measured separately.',heldout_check='No Dickens/Great Expectations/Forster match in formal evaluation or model configuration files at this assessment; v3 tests are original evaluation-only fiction.',generated_literary_targets=0)
 (OUT/'assessment.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
if __name__=='__main__':main()
